97	TEST_F(XdsOverrideHostTest, OverrideHost) {
98	  // Send address list to LB policy.
99	  const std::array<absl::string_view, 3> kAddresses = {
100	      "ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442", "ipv4:127.0.0.1:443"};
101	  auto picker = ExpectStartupWithRoundRobin(kAddresses);
102	  ASSERT_NE(picker, nullptr);
103	  // Check that the host is overridden
104	  std::map<UniqueTypeName, std::string> call_attributes{
105	      {XdsHostOverrideTypeName(), "127.0.0.1:442"}};
106	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[1]);
107	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[1]);
108	  call_attributes[XdsHostOverrideTypeName()] = std::string("127.0.0.1:441");
109	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[0]);
110	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[0]);
111	}
