113	TEST_F(XdsOverrideHostTest, OverrideHostSubchannelNotFound) {
114	  // Send address list to LB policy.
115	  const std::array<absl::string_view, 3> kAddresses = {
116	      "ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442", "ipv4:127.0.0.1:443"};
117	  auto picker = ExpectStartupWithRoundRobin(kAddresses);
118	  ASSERT_NE(picker, nullptr);
119	  std::map<UniqueTypeName, std::string> call_attributes{
120	      {XdsHostOverrideTypeName(), "no such host"}};
121	  ExpectRoundRobinPicks(picker.get(), kAddresses, call_attributes);
122	}
